@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'GL Account Search Help Data Definition'
define root view entity ZFI003_DD_GLACCOUNT_SHD
  as select from I_GLAccountText as glt
  inner join   I_GLAccountInCompanyCode as coa
    on coa.GLAccount = glt.GLAccount
  inner join   I_CompanyCode as cc
    on  cc.CompanyCode     = coa.CompanyCode
    and cc.ChartOfAccounts = glt.ChartOfAccounts
{
  key glt.GLAccount,
  key coa.CompanyCode,
      glt.GLAccountLongName
}
where
      glt.ChartOfAccounts = 'YCOA'
  and glt.Language        = $session.system_language
